import numpy as np

class GSLMatrix:
    @staticmethod
    def gsl_matrix_alloc(rows, cols):
        return gsl.gsl_matrix_alloc(rows, cols)

    @staticmethod
    def gsl_matrix_free(matrix):
        gsl.gsl_matrix_free(matrix)

    @staticmethod
    def numpy_to_gsl_matrix(np_array):
        rows, cols = np_array.shape
        gsl_matrix = GSLMatrix.gsl_matrix_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl_matrix.contents.data[i * cols + j] = np_array[i, j]
        return gsl_matrix

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix):
        rows = gsl_matrix.contents.size1
        cols = gsl_matrix.contents.size2
        np_array = np.zeros((rows, cols), dtype=np.float64)
        for i in range(rows):
            for j in range(cols):
                np_array[i, j] = gsl_matrix.contents.data[i * cols + j]
        return np_array

def compute_covariance(jacobian, epsrel, cov_matrix_dim):
    if not isinstance(jacobian, np.ndarray) or jacobian.ndim != 2:
        raise ValueError('Jacobian must be a 2D numpy array.')
    if not isinstance(epsrel, float):
        raise ValueError('Relative error tolerance must be a float.')
    if not isinstance(cov_matrix_dim, int) or cov_matrix_dim <= 0:
        raise ValueError('Covariance matrix dimension must be a positive integer.')

    rows, cols = jacobian.shape
    if cols != cov_matrix_dim:
        raise ValueError('Number of columns in Jacobian must match covariance matrix dimension.')

    gsl_jacobian = GSLMatrix.numpy_to_gsl_matrix(jacobian)
    cov_matrix = GSLMatrix.gsl_matrix_alloc(cov_matrix_dim, cov_matrix_dim)

    status = gsl.gsl_multifit_covar(gsl_jacobian, epsrel, cov_matrix)
    if status != 0:
        GSLMatrix.gsl_matrix_free(gsl_jacobian)
        GSLMatrix.gsl_matrix_free(cov_matrix)
        raise RuntimeError('Error in gsl_multifit_covar: {}'.format(status))

    covariance = GSLMatrix.gsl_matrix_to_numpy(cov_matrix)
    GSLMatrix.gsl_matrix_free(gsl_jacobian)
    GSLMatrix.gsl_matrix_free(cov_matrix)
    return covariance

