import numpy as np
import ctypes

# Load the GSL libraries
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define the required GSL types and functions
class GSLMatrix(ctypes.Structure):
    _fields_ = [("size1", ctypes.c_size_t), ("size2", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

class GSLVector(ctypes.Structure):
    _fields_ = [("size", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

class GSLEigenGenSymmWorkspace(ctypes.Structure):
    _fields_ = []

# Function to convert numpy array to GSL matrix
def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array.")
    if np_array.ndim != 2:
        raise ValueError("Input array must be 2-dimensional.")
    size1, size2 = np_array.shape
    data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return GSLMatrix(size1=size1, size2=size2, data=data)

# Function to convert numpy array to GSL vector
def numpy_to_gsl_vector(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array.")
    if np_array.ndim != 1:
        raise ValueError("Input array must be 1-dimensional.")
    size = np_array.size
    data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return GSLVector(size=size, data=data)

# Function to compute generalized symmetric eigenvalues
def compute_gensymm_eigenvalues(A, B):
    if A.shape != B.shape:
        raise ValueError("Matrices A and B must have the same dimensions.")
    n = A.shape[0]
    gsl_A = numpy_to_gsl_matrix(A)
    gsl_B = numpy_to_gsl_matrix(B)
    eigenvalues = np.zeros(n)
    gsl_eigenvalues = numpy_to_gsl_vector(eigenvalues)
    workspace = GSLEigenGenSymmWorkspace()
    gsl.gsl_eigen_gensymm_alloc(n, ctypes.byref(workspace))
    result = gsl.gsl_eigen_gensymm(gsl_A, gsl_B, ctypes.byref(gsl_eigenvalues), ctypes.byref(workspace))
    if result != 0:
        raise RuntimeError("Error computing eigenvalues.")
    gsl.gsl_eigen_gensymm_free(ctypes.byref(workspace))
    return eigenvalues

