        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.matrix = ctypes.create_string_buffer(self.rows * self.cols * ctypes.sizeof(ctypes.c_double))
        self.ptr = ctypes.cast(self.matrix, ctypes.POINTER(ctypes.c_double))

    def free(self):
        del self.matrix

    def to_numpy(self):
        return np.frombuffer(self.matrix, dtype=np.float64).reshape((self.rows, self.cols))

