class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = np.array(matrix, dtype=np.float64)
        self.rows, self.cols = self.matrix.shape
        if self.rows != self.cols:
            raise ValueError('Input must be a square matrix')

    def to_gsl(self):
        return self.matrix.ctypes.data

    def is_positive_definite(self):
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int]
        gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int
        result = gsl.gsl_linalg_cholesky_decomp(self.to_gsl(), self.rows)
        return result == 0

    def cholesky_decomp(self):
        if not self.is_positive_definite():
            raise ValueError('Matrix is not positive definite')
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int]
        gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int
        gsl.gsl_linalg_cholesky_decomp(self.to_gsl(), self.rows)
        return self.matrix.tolist()

