class GslRstatQuantileWorkspace:
    def __init__(self, p):
        self.p = p
        self.workspace = gsl.gsl_rstat_quantile_alloc()
        if not self.workspace:
            raise MemoryError('Failed to allocate quantile workspace')

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self.workspace, value)

    def get(self):
        return gsl.gsl_rstat_quantile_get(self.workspace)

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace)

def compute_quantile(p, values):
    if not (0 <= p <= 1):
        raise ValueError('Quantile p must be between 0 and 1')
    workspace = GslRstatQuantileWorkspace(p)
    try:
        for value in values:
            workspace.add(value)
        return workspace.get()
    finally:
        workspace.free()

